 p=root/f'{id}.json';d=json.loads(p.read_text());before=json.loads(json.dumps(d));existing={s['title'] for s in d['sections']}
 for title,paragraphs in sections:
  if title not in existing:d['sections'].append({'title':title,'paragraphs':paragraphs})
 for source in extra_sources[id]:
  if source not in d['sources']:d['sources'].append(source)
 assert d['sections'][:len(before['sections'])]==before['sections']
 words=len(' '.join(p for s in d['sections'] for p in s['paragraphs']).split())
 assert 700<=words<=1000,(id,words)
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(id,words)
